-- Keep published guidance aligned with the implemented portal, without inventing school policy.
CREATE TEMP TABLE faq_guidance_refresh(category text,question text,answer text,keywords text) ON COMMIT DROP;
DO $$ DECLARE target text; BEGIN
 FOR target IN SELECT DISTINCT unnest(ARRAY['public','imcc_review']) LOOP
  EXECUTE format('UPDATE %I.faq_articles f SET category=p.category,answer=p.answer,keywords=p.keywords FROM pg_temp.faq_guidance_refresh p WHERE f.question=p.question AND (f.category,f.answer,f.keywords) IS DISTINCT FROM (p.category,p.answer,p.keywords)',target);
  EXECUTE format('INSERT INTO %I.faq_articles(category,question,answer,keywords,is_active) SELECT p.category,p.question,p.answer,p.keywords,true FROM pg_temp.faq_guidance_refresh p WHERE NOT EXISTS(SELECT 1 FROM %I.faq_articles f WHERE f.question=p.question)',target,target);
 END LOOP;
END $$;
